/**
 * Parse value as a base-10 integer and clamp it inclusively between min and max.
 * Returns fallback when value does not parse to an integer.
 * Explicit zero is valid and must not be mistaken for invalid input.
 */
export function clampInteger(value, fallback, min, max) {
  // Handle explicit zero and other numbers directly
  if (typeof value === 'number' && Number.isInteger(value)) {
    return Math.min(Math.max(value, min), max);
  }

  // Parse string values
  if (typeof value === 'string') {
    const trimmed = value.trim();
    // Empty string is invalid
    if (trimmed === '') {
      return fallback;
    }
    // Check if it's a valid integer string (no decimals, no scientific notation)
    if (!/^[+-]?\d+$/.test(trimmed)) {
      return fallback;
    }
    const parsed = parseInt(trimmed, 10);
    if (!Number.isInteger(parsed)) {
      return fallback;
    }
    return Math.min(Math.max(parsed, min), max);
  }

  // All other types (null, undefined, objects, arrays, floats, etc.) return fallback
  return fallback;
}
